<template>
  <view class="container">
    <button @tap="chooseImage">选择/拍摄照片</button>
    <image v-if="imgSrc" :src="imgSrc" mode="aspectFit" style="width: 300px; height: 300px;" />

    <view v-if="score">
      <text>评分：</text><text style="font-weight: bold;">{{ score }}</text>
    </view>
    <view v-if="advice" class="result">
      <text>AI 建议：</text>
      <text>{{ advice }}</text>
    </view>

    <view class="checkbox">
      <checkbox :checked="saveAsTemplate" @change="saveAsTemplate = !saveAsTemplate" />
      <text>保存为模版</text>
    </view>

    <button v-if="imgSrc" @tap="submitTemplate">提交分析</button>
  </view>
</template>

<script>
export default {
  data() {
    return {
      imgSrc: '',
      score: '',
      advice: '',
      saveAsTemplate: false
    }
  },
  methods: {
    chooseImage() {
      uni.chooseImage({
        count: 1,
        sourceType: ['camera', 'album'],
        success: (res) => {
          this.imgSrc = res.tempFilePaths[0]
          this.score = ''
          this.advice = ''
        }
      })
    },
    submitTemplate() {
      if (!this.imgSrc) return
      uni.uploadFile({
        url: 'http://192.168.1.3:5001/analyze-template',
        filePath: this.imgSrc,
        name: 'file',
        formData: {
          save_as_template: this.saveAsTemplate ? 'true' : 'false'
        },
        success: (res) => {
          const data = JSON.parse(res.data)
          if (data.error) {
            uni.showToast({ title: '分析失败', icon: 'none' })
            return
          }
          this.score = data.score
          this.advice = data.advice
          if (this.saveAsTemplate) {
            uni.showToast({ title: '已保存到模版', icon: 'success' })
          }
        },
        fail: (err) => {
          console.error(err)
          uni.showToast({ title: '上传失败', icon: 'none' })
        }
      })
    }
  }
}
</script>

<style>
.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 40px;
}
.result {
  margin-top: 20px;
  font-size: 16px;
  color: #333;
  text-align: center;
}
.checkbox {
  display: flex;
  align-items: center;
  margin: 20px 0;
}
</style>
